exercises.solutionCode:
#include <stddef.h>
typedef struct {
    unsigned int origin;
    unsigned int length;
} MemRegion;

typedef struct {
    unsigned int size;
    unsigned int align;
} SectionSpec;

static int is_power_of_two(unsigned int value)
{
    return (value != 0u) && ((value & (value - 1u)) == 0u);
}

static int align_up(unsigned int addr, unsigned int align, unsigned int *out)
{
    unsigned int mask = align - 1u;
    unsigned int aligned = (addr + mask) & ~mask;

    if (aligned < addr) {
        return -1;  /* 无符号回绕：地址空间已用尽 */
    }
    *out = aligned;
    return 0;
}

int layout_sections(const MemRegion *region, const SectionSpec *specs,
                    int count, unsigned int *out_starts)
{
    unsigned int cursor;
    unsigned int limit;
    int i;

    if (region == NULL || specs == NULL || out_starts == NULL || count <= 0) {
        return -1;
    }
    if (region->length == 0u) {
        return -1;
    }

    limit = region->origin + region->length;
    if (limit < region->origin) {
        return -1;  /* ORIGIN + LENGTH 溢出，区域本身非法 */
    }
    cursor = region->origin;

    for (i = 0; i < count; i++) {
        unsigned int start = 0u;

        if (specs[i].size == 0u || !is_power_of_two(specs[i].align)) {
            return -1;
        }
        if (align_up(cursor, specs[i].align, &start) != 0) {
            return 1;
        }
        if (start > limit || specs[i].size > limit - start) {
            return 1;
        }

        out_starts[i] = start;
        cursor = start + specs[i].size;
    }

    return 0;
}
